#include <iostream>
#include <algorithm>
#include <numeric>
#include <cmath>
using namespace std;

long long gcd_custom(long long a, long long b) {
    while (b != 0) {
        long long temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

long long lcm_custom(long long a, long long b) {
    return a / gcd_custom(a, b) * b;
}

struct FractionType {
    long long numerator;
    long long denominator;
};

FractionType get_abs(const FractionType& f) {
    return {abs(f.numerator), f.denominator};
}

int compare_fraction(const FractionType& a, const FractionType& b) {
    long long l = lcm_custom(a.denominator, b.denominator);
    long long na = a.numerator * (l / a.denominator);
    long long nb = b.numerator * (l / b.denominator);
    if (na == nb) return 0;
    return (na < nb) ? -1 : 1;
}

FractionType subtract_fraction(const FractionType& a, const FractionType& b) {
    long long l = lcm_custom(a.denominator, b.denominator);
    long long na = a.numerator * (l / a.denominator);
    long long nb = b.numerator * (l / b.denominator);
    long long res_num = na - nb;
    long long g = gcd_custom(abs(res_num), l);
    return {res_num / g, l / g};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long x, y, n;
    cin >> x >> y >> n;
    long long g = gcd_custom(x, y);
    x /= g; y /= g;
    FractionType xy = {x, y};
    FractionType min_diff = {1000000000000LL, 1};
    FractionType min_val = {0, 0};
    for (long long b = 1; b <= n; ++b) {
        long long l = 0, r = 1000000;
        double maxv = (double)x / y + (double)min_diff.numerator / min_diff.denominator + 2;
        maxv *= b;
        r = (long long)maxv;
        while (l <= r) {
            long long mid = l + (r - l) / 2;
            FractionType candidate = {mid, b};
            FractionType diff = get_abs(subtract_fraction(xy, candidate));
            int cmp = compare_fraction(diff, min_diff);
            if (cmp == 0) {
                if (candidate.denominator < min_val.denominator)
                    min_val = candidate;
                else if (candidate.denominator == min_val.denominator && candidate.numerator < min_val.numerator)
                    min_val = candidate;
            } else if (cmp < 0) {
                min_diff = diff;
                min_val = candidate;
            }
            if (compare_fraction(candidate, xy) < 0)
                l = mid + 1;
            else
                r = mid - 1;
        }
    }
    cout << min_val.numerator << "/" << min_val.denominator;
    return 0;
}
